package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Closed original SoupX API contracts; historical density and current gamma estimators stay distinct. */
final class SoupXWorkflowRequest {
    private SoupXWorkflowRequest() { }
    record Request(String version,String format,String clusters,String relation,Path rawCounts,Path filteredCounts,
                   Path genes,Path droplets,Path cells,Path geneSets,Path mask,Path perCellRho,Path source,
                   List<Object> soupRange,List<Map<String,Object>> analyses,Path out,Path rscript,Path rHome,List<Path> libraries,
                   long inputBytes,int maximumGenes,int maximumDroplets,int maximumCells,int inputEntries,int intermediateEntries,
                   int chunkEntries,int outputFiles,int jsonBytes,int jsonNodes,long outputBytes,long auditOperations,int timeout){
        Map<String,Object> parameters(){return values("version",version,"matrix_format",format,"clusters",clusters,"counts_relation",relation,"soup_range",soupRange,"analyses",analyses,"gene_sets_provided",geneSets!=null,"mask_provided",mask!=null,"rho_by_cell_provided",perCellRho!=null,"maximum_intermediate_entries",intermediateEntries,"transport_chunk_entries",chunkEntries);}
        Map<String,Object> effective(){var m=parameters();m.putAll(values("count_units","raw-integer-counts","raw_counts",rawCounts.toString(),"filtered_counts",filteredCounts.toString(),"gene_metadata",genes.toString(),"droplet_metadata",droplets.toString(),"cell_metadata",cells.toString(),"soup_source",source.toString(),"out",out.toString(),"rscript",rscript.toString(),"r_home",rHome.toString(),"r_libraries",libraries.stream().map(Path::toString).toList(),"maximum_input_bytes",inputBytes,"maximum_genes",maximumGenes,"maximum_droplets",maximumDroplets,"maximum_cells",maximumCells,"maximum_input_entries",inputEntries,"maximum_output_files",outputFiles,"maximum_json_bytes",jsonBytes,"maximum_json_nodes",jsonNodes,"maximum_output_bytes",outputBytes,"maximum_audit_operations",auditOperations,"timeout_seconds",timeout));if(geneSets!=null)m.put("gene_sets",geneSets.toString());if(mask!=null)m.put("nonexpression_mask",mask.toString());if(perCellRho!=null)m.put("rho_by_cell",perCellRho.toString());return m;}
    }
    static Request parse(Map<String,Object> m,Path parent)throws IOException{
        allowed(m,"schema_version","mode","version","count_units","matrix_format","clusters","counts_relation","raw_counts","filtered_counts","gene_metadata","droplet_metadata","cell_metadata","gene_sets","nonexpression_mask","rho_by_cell","soup_source","soup_range","analyses","out","rscript","r_home","r_libraries","maximum_input_bytes","maximum_genes","maximum_droplets","maximum_cells","maximum_input_entries","maximum_intermediate_entries","transport_chunk_entries","maximum_output_files","maximum_json_bytes","maximum_json_nodes","maximum_output_bytes","maximum_audit_operations","timeout_seconds");
        integer(m.get("schema_version"),1,1);require(text(m.get("mode")).equals("AMBIENT"),"Declare AMBIENT mode");String version=choice(m.get("version"),"1.6.2","1.3.0"),format=choice(m.get("matrix_format"),"matrix-market","dense-tsv"),clusters=choice(m.get("clusters"),"supplied","none"),relation=choice(m.get("counts_relation"),"raw-subset","supplied-independent");require(text(m.get("count_units")).equals("raw-integer-counts"),"Raw nonnegative integer counts required; no transformed-count substitution");
        var range=range(m.get("soup_range"),0,9007199254740991.0);var libraries=new ArrayList<Path>();for(Object o:list(m.get("r_libraries"))){require(libraries.size()<64,"At most64 explicit private R libraries");Path path=resolve(parent,label(o));require(!libraries.contains(path),"Duplicate R library path");libraries.add(path);}require(!libraries.isEmpty(),"Declare exact private R libraries");
        boolean needsGenes=false,needsMask=false,needsRho=false;var analyses=new ArrayList<Map<String,Object>>();var ids=new HashSet<String>();
        for(Object o:list(m.get("analyses"))){
            require(analyses.size()<32,"At most32 analysis cases");var a=object(o);allowed(a,"id","seed","estimation","adjustment");String id=text(a.get("id"));require(id.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,63}")&&ids.add(id.toLowerCase(Locale.ROOT)),"Unique portable case-folded analysis IDs required");integer(a.get("seed"),0,2147483647);var e=object(a.get("estimation"));String kind=text(e.get("kind"));
            switch(kind){
                case "fixed"->{
                    allowed(e,"kind","rho_mode","rho","force_accept");String mode=choice(e.get("rho_mode"),"constant","per-cell");if(mode.equals("constant"))finite(e.get("rho"),0,1);else{needsRho=true;require(!e.containsKey("rho"),"Per-cell rho refuses unused scalar rho");}force(e,version);
                }
                case "manual-global-poisson"->{
                    allowed(e,"kind","mask_mode","clustering_scope","maximum_contamination","fdr","force_accept","cell_specific");needsGenes=true;String mask=choice(e.get("mask_mode"),"provided","estimate");
                    if(mask.equals("provided")){needsMask=true;for(String key:List.of("clustering_scope","maximum_contamination","fdr"))require(!e.containsKey(key),"Provided mask refuses unused mask-estimation setting: "+key);}
                    else{scope(e.get("clustering_scope"),clusters);finite(e.get("maximum_contamination"),0,1);finite(e.get("fdr"),0,1);}
                    force(e,version);if(version.equals("1.3.0"))require(!bool(e.get("cell_specific")),"Cell-specific STAN needs a separate typed/runtime profile; this mode explicitly selects the original global Poisson GLM");else require(!e.containsKey("cell_specific"),"Current source has no cellSpecificEstimates argument");
                }
                case "automatic-gamma"->{
                    require(version.equals("1.6.2"),"Automatic gamma/SoupChannel return belongs to1.6.2; no historical API translation");require(clusters.equals("supplied"),"Automatic estimation requires supplied clusters");allowed(e,"kind","marker_selection","tfidf_min","soup_quantile","maximum_markers","contamination_range","rho_max_fdr","prior_rho","prior_rho_sd","force_accept");require(text(e.get("marker_selection")).equals("original-quickMarkers-defaults"),"Declare original quickMarkers marker derivation; external marker tables require their own typed contract");finite(e.get("tfidf_min"),0,1e12);finite(e.get("soup_quantile"),0,1);integer(e.get("maximum_markers"),1,1000000);range(e.get("contamination_range"),0,1);finite(e.get("rho_max_fdr"),0,1);positive(e.get("prior_rho"),1);positive(e.get("prior_rho_sd"),1e12);force(e,version);
                }
                case "automatic-legacy-density"->{
                    require(version.equals("1.3.0"),"Legacy density/data-frame return belongs to1.3.0; no current API translation");require(clusters.equals("supplied"),"Automatic estimation requires supplied clusters");allowed(e,"kind","marker_selection","number_markers","tfidf_min","soup_min","rho_max","fdr","minimum_counts","density","apply_density_mode");require(text(e.get("marker_selection")).equals("original-quickMarkers-defaults"),"Declare original historical marker derivation");integer(e.get("number_markers"),1,1000000);finite(e.get("tfidf_min"),0,1e12);finite(e.get("soup_min"),0,1);finite(e.get("rho_max"),0,1);finite(e.get("fdr"),0,1);finite(e.get("minimum_counts"),0,9007199254740991.0);density(object(e.get("density")));boolean apply=bool(e.get("apply_density_mode"));if(a.get("adjustment")!=null)require(apply,"Legacy autoEstCont returns a table. Explicit apply_density_mode=true is required before correction; no automatic return-type substitution");
                }
                default->throw new IOException("Unsupported explicit SoupX estimator: "+kind);
            }
            require(a.containsKey("adjustment"),"Declare adjustment object or explicit null for estimation-only");
            if(a.get("adjustment")!=null){var d=object(a.get("adjustment"));allowed(d,"method","clustering_scope","round_to_integer","tolerance","p_cut");choice(d.get("method"),"subtraction","soupOnly","multinomial");scope(d.get("clustering_scope"),clusters);bool(d.get("round_to_integer"));positive(d.get("tolerance"),1e12);finite(d.get("p_cut"),0,1);}
            analyses.add(Collections.unmodifiableMap(a));
        }
        require(!analyses.isEmpty(),"Require1..32 analyses");require(m.containsKey("gene_sets")==needsGenes,"Provide gene_sets exactly when manual estimation uses it");require(m.containsKey("nonexpression_mask")==needsMask,"Provide nonexpression_mask exactly when a supplied mask is requested");require(m.containsKey("rho_by_cell")==needsRho,"Provide rho_by_cell exactly when per-cell fixed rho is requested");
        return new Request(version,format,clusters,relation,path(m,"raw_counts",parent),path(m,"filtered_counts",parent),path(m,"gene_metadata",parent),path(m,"droplet_metadata",parent),path(m,"cell_metadata",parent),needsGenes?path(m,"gene_sets",parent):null,needsMask?path(m,"nonexpression_mask",parent):null,needsRho?path(m,"rho_by_cell",parent):null,path(m,"soup_source",parent),range,List.copyOf(analyses),path(m,"out",parent),path(m,"rscript",parent),path(m,"r_home",parent),List.copyOf(libraries),number(m,"maximum_input_bytes",134217728,1,536870912),(int)number(m,"maximum_genes",200000,2,1000000),(int)number(m,"maximum_droplets",1000000,1,10000000),(int)number(m,"maximum_cells",100000,2,1000000),(int)number(m,"maximum_input_entries",1000000,1,25000000),(int)number(m,"maximum_intermediate_entries",5000000,1,100000000),(int)number(m,"transport_chunk_entries",50000,1,500000),(int)number(m,"maximum_output_files",100000,1,1000000),(int)number(m,"maximum_json_bytes",67108864,1,536870912),(int)number(m,"maximum_json_nodes",10000000,1,200000000),number(m,"maximum_output_bytes",1073741824,1,137438953472L),number(m,"maximum_audit_operations",100000000,1,100000000000L),(int)number(m,"timeout_seconds",600,1,86400));
    }
    private static void density(Map<String,Object> d)throws IOException{allowed(d,"bandwidth","adjust","kernel","n","cut","ext","old_coordinates");Object bw=d.get("bandwidth");if(bw instanceof String)choice(bw,"nrd0","nrd","ucv","bcv","SJ-ste","SJ-dpi");else positive(bw,1e12);positive(d.get("adjust"),1e12);choice(d.get("kernel"),"gaussian","epanechnikov","rectangular","triangular","biweight","cosine","optcosine");integer(d.get("n"),512,1048576);finite(d.get("cut"),0,1e12);positive(d.get("ext"),1e12);bool(d.get("old_coordinates"));}
    private static void force(Map<String,Object> e,String version)throws IOException{if(version.equals("1.6.2"))bool(e.get("force_accept"));else require(!e.containsKey("force_accept"),"Historical source has no forceAccept argument; it cannot be silently added");}
    private static void scope(Object value,String clusters)throws IOException{String s=choice(value,"cell-only","supplied-clusters");require(!s.equals("supplied-clusters")||clusters.equals("supplied"),"Cluster operation requires explicit supplied clusters");}
    private static List<Object> range(Object value,double min,double max)throws IOException{var v=list(value);require(v.size()==2,"Require an ordered two-number range");double low=finite(v.get(0),min,max),high=finite(v.get(1),min,max);require(low<high,"Require strict lower<upper range");return List.of(v.get(0),v.get(1));}
    private static void positive(Object value,double max)throws IOException{require(finite(value,Double.MIN_NORMAL,max)>0,"Require positive finite parameter");}
    private static String choice(Object value,String... choices)throws IOException{String s=text(value);require(Set.of(choices).contains(s),"Require one of "+String.join(", ",choices));return s;}
    private static Path path(Map<String,Object> m,String key,Path parent)throws IOException{return resolve(parent,label(m.get(key)));}
    private static void allowed(Map<String,Object> m,String... names)throws IOException{var keys=Set.of(names);for(String name:m.keySet())require(keys.contains(name),"Unknown SoupX workflow field: "+name);}
    private static Map<String,Object> values(Object... pairs){var m=new LinkedHashMap<String,Object>();for(int i=0;i<pairs.length;i+=2)m.put((String)pairs[i],pairs[i+1]);return m;}
}
